import type { EventAttributes } from "./types";

const MAX_VALUE_LENGTH = 4096;
const MAX_FLATTEN_DEPTH = 4;

export const truncateValue = (value: string, max = MAX_VALUE_LENGTH): string =>
  value.length > max ? value.slice(0, max) : value;

/**
 * Flatten nested metadata into dot-keyed scalar attributes. Non-scalar leaves
 * are JSON-stringified; strings are length-capped so a hostile or buggy page
 * cannot inflate rows.
 */
export const flattenAttributes = (
  input: Record<string, unknown>,
  prefix = "",
  depth = 0,
): EventAttributes => {
  const result: EventAttributes = {};

  for (const [key, rawValue] of Object.entries(input)) {
    const fullKey = prefix ? `${prefix}.${key}` : key;

    if (rawValue === null || rawValue === undefined) {
      continue;
    }

    if (
      typeof rawValue === "object" &&
      !Array.isArray(rawValue) &&
      depth < MAX_FLATTEN_DEPTH
    ) {
      Object.assign(
        result,
        flattenAttributes(
          rawValue as Record<string, unknown>,
          fullKey,
          depth + 1,
        ),
      );
      continue;
    }

    if (typeof rawValue === "number" || typeof rawValue === "boolean") {
      result[fullKey] = rawValue;
    } else if (typeof rawValue === "string") {
      result[fullKey] = truncateValue(rawValue);
    } else {
      try {
        result[fullKey] = truncateValue(JSON.stringify(rawValue) ?? "");
      } catch {
        // Circular or unserializable — drop rather than throw into the host.
      }
    }
  }

  return result;
};
