import { SDK_CONSOLE_PREFIX } from "./console";
import { consumeWrapperSeen } from "./network";
import { severityForStatus, urlPath } from "./network-event-format";
import type { WebEvent } from "./types";

export interface ResourceObserverOptions {
  emit(event: WebEvent): void;
  /** SDK-internal endpoints: never reported. */
  isInternalUrl(url: string): boolean;
  /** Would the active config have injected trace context into this URL? */
  isInjectionTarget(url: string): boolean;
}

export interface ResourceObserverHandle {
  teardown(): void;
}

/**
 * Patch-independent network visibility: PerformanceObserver resource timing
 * sees every fetch/XHR the page performs — including ones issued by clients
 * that captured the native functions before the SDK patched (`buffered: true`
 * also replays requests from before init). Wrapper-captured requests are
 * deduped out via the wrapper-seen ledger; the leftovers get a degraded
 * network event (no method, no trace id — observation cannot inject), plus a
 * once-per-origin instrumentation-gap diagnostic when the URL was an
 * injection target, so bypass is a visible signal instead of silent loss.
 */
export const installResourceObserver = (
  options: ResourceObserverOptions,
): ResourceObserverHandle => {
  if (typeof PerformanceObserver === "undefined") {
    return { teardown() {} };
  }

  const diagnosedOrigins = new Set<string>();

  const diagnoseBypass = (url: string): void => {
    let origin: string;
    try {
      origin = new URL(url).origin;
    } catch {
      return;
    }
    if (diagnosedOrigins.has(origin)) return;
    diagnosedOrigins.add(origin);

    const message = `requests to ${origin} bypass SDK instrumentation (fetch/XHR captured pre-init). Fix: import "@sazabi/browser/register" first.`;
    options.emit({
      type: "log",
      body: message,
      severity: "WARN",
      timeUnixMs: Date.now(),
      attributes: {
        "web.sdk.diagnostic": "instrumentation_gap",
        "web.sdk.bypassed_origin": origin,
      },
    });
    try {
      console.warn(`${SDK_CONSOLE_PREFIX} ${message}`);
    } catch {
      // Console unavailability is not our problem.
    }
  };

  const handleEntry = (entry: PerformanceResourceTiming): void => {
    try {
      if (
        entry.initiatorType !== "fetch" &&
        entry.initiatorType !== "xmlhttprequest"
      ) {
        return;
      }
      const url = entry.name;
      if (options.isInternalUrl(url)) return;
      if (consumeWrapperSeen(url, entry.startTime)) return;

      // Typed required in current lib.dom, but absent in older engines.
      const status = (entry.responseStatus as number | undefined) ?? 0;
      const completedAtMs = Math.round(
        performance.timeOrigin + entry.startTime + entry.duration,
      );

      options.emit({
        type: "network",
        body: `request ${urlPath(url)} → ${status > 0 ? status : "observed"}`,
        severity: status > 0 ? severityForStatus(status) : "INFO",
        timeUnixMs: completedAtMs,
        attributes: {
          "http.response.status_code": status > 0 ? status : undefined,
          "url.full": url,
          "web.network.kind": entry.initiatorType === "fetch" ? "fetch" : "xhr",
          "web.network.duration_ms": Math.round(entry.duration),
          "web.network.source": "resource-timing",
        },
      });

      if (options.isInjectionTarget(url)) {
        diagnoseBypass(url);
      }
    } catch {
      // Observation failures must never surface to the host.
    }
  };

  let observer: PerformanceObserver;
  try {
    observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        handleEntry(entry as PerformanceResourceTiming);
      }
    });
    observer.observe({ type: "resource", buffered: true });
  } catch {
    return { teardown() {} };
  }

  return {
    teardown() {
      try {
        observer.disconnect();
      } catch {
        // Best-effort.
      }
    },
  };
};
