import { isWrapped, markWrapped } from "./patch-marker";
import type { ConsoleCaptureLevel, EventSeverity, WebEvent } from "./types";

export interface ConsoleCaptureOptions {
  emit(event: WebEvent): void;
  levels: ConsoleCaptureLevel[];
}

export interface ConsoleCaptureHandle {
  teardown(): void;
}

/** SDK-emitted console lines carry this prefix and are never re-captured. */
export const SDK_CONSOLE_PREFIX = "[@sazabi/browser]";

const SEVERITY_BY_LEVEL: Record<ConsoleCaptureLevel, EventSeverity> = {
  error: "ERROR",
  warn: "WARN",
  info: "INFO",
  debug: "DEBUG",
};

const MAX_ARG_CHARS = 1_000;
const MAX_BODY_CHARS = 4_000;

const stringifyArg = (value: unknown): string => {
  let text: string;
  if (typeof value === "string") {
    text = value;
  } else if (value instanceof Error) {
    text = `${value.name}: ${value.message}`;
  } else {
    try {
      text = JSON.stringify(value) ?? String(value);
    } catch {
      text = String(value);
    }
  }
  return text.length > MAX_ARG_CHARS
    ? `${text.slice(0, MAX_ARG_CHARS)}…`
    : text;
};

/**
 * Mirror selected console levels into the event stream as `log` events.
 * The original console method always runs first — devtools behavior is never
 * altered — and capture failures are swallowed. Lines the SDK itself prints
 * (prefixed with SDK_CONSOLE_PREFIX) are skipped to avoid self-capture.
 */
export const installConsoleCapture = (
  options: ConsoleCaptureOptions,
): ConsoleCaptureHandle => {
  const restores: Array<() => void> = [];
  let emitting = false;

  for (const level of options.levels) {
    const original = console[level];
    if (typeof original !== "function" || isWrapped(original)) {
      continue;
    }

    const wrapped = function (this: unknown, ...args: unknown[]): void {
      original.apply(this ?? console, args);
      if (emitting) return;
      try {
        if (
          typeof args[0] === "string" &&
          args[0].startsWith(SDK_CONSOLE_PREFIX)
        ) {
          return;
        }
        emitting = true;
        const body = args.map(stringifyArg).join(" ").slice(0, MAX_BODY_CHARS);
        options.emit({
          type: "log",
          body: body || `console.${level}`,
          severity: SEVERITY_BY_LEVEL[level],
          timeUnixMs: Date.now(),
          attributes: {
            "web.console.level": level,
          },
        });
      } catch {
        // Capture failures must never surface to the host.
      } finally {
        emitting = false;
      }
    };

    markWrapped(wrapped);
    console[level] = wrapped as typeof original;
    restores.push(() => {
      if (console[level] === wrapped) {
        console[level] = original;
      }
    });
  }

  return {
    teardown() {
      for (const restore of restores) {
        try {
          restore();
        } catch {
          // Best-effort restore.
        }
      }
    },
  };
};
