const SESSION_STORAGE_KEY = "sazabi.session";
const WINDOW_STORAGE_KEY = "sazabi.windowId";
const DISTINCT_STORAGE_KEY = "sazabi.distinctId";

const SESSION_IDLE_MS = 30 * 60 * 1000;
const SESSION_MAX_MS = 24 * 60 * 60 * 1000;
/** Throttle localStorage activity writes; click bursts must not spam storage. */
const ACTIVITY_PERSIST_INTERVAL_MS = 5_000;

interface StoredSession {
  id: string;
  startedAt: number;
  lastActivityAt: number;
}

export interface SessionManager {
  getSessionId(): string;
  getWindowId(): string;
  getDistinctId(): string | undefined;
  /**
   * Set the client-asserted identity. Switching from one identity directly
   * to a different one rotates the session and window ids so two users on a
   * shared device never thread into one timeline.
   */
  setDistinctId(distinctId: string): void;
  /** Logout: clear identity and rotate both session and window ids. */
  reset(): void;
  /** Record user activity; may rotate the session on idle/max-age expiry. */
  touch(): void;
}

const randomSuffix = (): string => {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
};

const newId = (prefix: string): string =>
  `${prefix}_${Date.now().toString(36)}${randomSuffix()}`;

/**
 * Storage access that degrades to in-memory when storage is unavailable
 * (Safari private mode, disabled cookies, sandboxed iframes). A degraded
 * session is per-page rather than cross-tab — acceptable fallback.
 */
const createSafeStorage = (
  getStore: () => Storage,
): {
  get(key: string): string | null;
  set(key: string, value: string): void;
  remove(key: string): void;
} => {
  const memory = new Map<string, string>();
  return {
    get(key) {
      try {
        return getStore().getItem(key);
      } catch {
        return memory.get(key) ?? null;
      }
    },
    set(key, value) {
      try {
        getStore().setItem(key, value);
      } catch {
        memory.set(key, value);
      }
    },
    remove(key) {
      memory.delete(key);
      try {
        getStore().removeItem(key);
      } catch {
        // Fallback map already cleared.
      }
    },
  };
};

const parseStoredSession = (raw: string | null): StoredSession | undefined => {
  if (!raw) return undefined;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof (parsed as StoredSession).id === "string" &&
      typeof (parsed as StoredSession).startedAt === "number" &&
      typeof (parsed as StoredSession).lastActivityAt === "number"
    ) {
      return parsed as StoredSession;
    }
  } catch {
    // Corrupt value — treat as absent and rotate.
  }
  return undefined;
};

/**
 * Cross-tab session identity. `session.id` is the visit (localStorage, shared
 * across tabs, last-writer-wins on rotation races — a split session is
 * cosmetic, not data loss). `session.window_id` is this tab (sessionStorage).
 * `session.distinct_id` is read through storage so identify/reset in one tab
 * is visible to sibling tabs on their next event.
 */
export const createSessionManager = (): SessionManager => {
  const local = createSafeStorage(() => window.localStorage);
  const session = createSafeStorage(() => window.sessionStorage);

  let lastPersistedActivity = 0;

  const readOrRotate = (): StoredSession => {
    const now = Date.now();
    const stored = parseStoredSession(local.get(SESSION_STORAGE_KEY));

    if (
      stored &&
      now - stored.lastActivityAt <= SESSION_IDLE_MS &&
      now - stored.startedAt <= SESSION_MAX_MS
    ) {
      return stored;
    }

    const fresh: StoredSession = {
      id: newId("sess"),
      startedAt: now,
      lastActivityAt: now,
    };
    local.set(SESSION_STORAGE_KEY, JSON.stringify(fresh));
    lastPersistedActivity = now;
    return fresh;
  };

  let windowId = session.get(WINDOW_STORAGE_KEY);
  if (!windowId) {
    windowId = newId("win");
    session.set(WINDOW_STORAGE_KEY, windowId);
  }

  const rotate = (): void => {
    const now = Date.now();
    local.set(
      SESSION_STORAGE_KEY,
      JSON.stringify({
        id: newId("sess"),
        startedAt: now,
        lastActivityAt: now,
      }),
    );
    lastPersistedActivity = now;
    windowId = newId("win");
    session.set(WINDOW_STORAGE_KEY, windowId);
  };

  return {
    getSessionId() {
      return readOrRotate().id;
    },
    getWindowId() {
      return windowId as string;
    },
    getDistinctId() {
      return local.get(DISTINCT_STORAGE_KEY) ?? undefined;
    },
    setDistinctId(id: string) {
      const current = local.get(DISTINCT_STORAGE_KEY) ?? undefined;
      if (current !== undefined && current !== id) {
        // Identity switch without reset(): defensive rotation so the new
        // user's events never join the previous user's session.
        rotate();
      }
      local.set(DISTINCT_STORAGE_KEY, id);
    },
    reset() {
      local.remove(DISTINCT_STORAGE_KEY);
      rotate();
    },
    touch() {
      const now = Date.now();
      const current = readOrRotate();
      if (now - lastPersistedActivity >= ACTIVITY_PERSIST_INTERVAL_MS) {
        local.set(
          SESSION_STORAGE_KEY,
          JSON.stringify({ ...current, lastActivityAt: now }),
        );
        lastPersistedActivity = now;
      }
    },
  };
};
