/**
 * Resolving the intake endpoint from a single URL.
 *
 * Every other Sazabi log source is configured with one intake URL, and public
 * keys are meant to stay a low-level detail customers never handle. The key is
 * already in the URL: the intake edge reconstructs it from the hostname
 * (terraform/main/cloudfront-functions/intake-router.js), so the SDK can do the
 * same reconstruction locally and send the Bearer header itself.
 *
 * Two keyed shapes exist, matching the edge's two grammars:
 *   {hex}.{region}.intake.{domain}            — prefixless (what log sources issue)
 *   {adapter}-{hex}.{region}.intake.{domain}  — keyed-adapter (legacy, still served)
 *
 * A URL in neither shape is not an error: it may be a proxy or a custom
 * endpoint. The SDK then requires an explicit `publicKey`, so a
 * misconfiguration surfaces as a clear warning rather than silent no-auth.
 */

const KEYED_HOST = /^([0-9a-f]{32})\./;
const KEYED_ADAPTER_HOST = /^[a-z0-9-]+?-([0-9a-f]{32})\./;

export interface ResolvedIntakeEndpoint {
  /**
   * Base to POST to — origin plus any proxy path prefix, no trailing slash.
   * The transport appends `/v1/logs`.
   */
  baseUrl: string;
  /** Credential for the Authorization header, derived or explicit. */
  publicKey: string;
}

/** Public key embedded in a keyed intake hostname, if it carries one. */
export const publicKeyFromIntakeUrl = (url: string): string | undefined => {
  let host: string;
  try {
    host = new URL(url).hostname;
  } catch {
    return undefined;
  }
  const hex = (KEYED_HOST.exec(host) ?? KEYED_ADAPTER_HOST.exec(host))?.[1];
  return hex ? `sazabi_public_${hex}` : undefined;
};

/**
 * Normalize a configured intake URL to a base the transport can suffix with
 * `/v1/logs`: drop a terminal `/v1/logs` so both the bare host and the full
 * OTLP endpoint work (the two forms customers copy from setup instructions),
 * and drop query/hash, which the OTLP POST has no use for.
 *
 * A path prefix is preserved. Reducing this to `origin` would break the
 * documented proxy escape hatch two ways: records for a proxy mounted at
 * `https://example.com/otel` would go to `/v1/logs`, and the internal-request
 * filter — a `startsWith` on this base — would suppress network capture for
 * every request sharing that origin, including the customer's own API traffic.
 *
 * Only `http:` and `https:` resolve. Any other scheme would leave the SDK
 * looking initialized while `fetch` rejects the protocol and the transport
 * swallows the error, dropping every event; failing closed here surfaces the
 * misconfiguration as the same init warning as a missing URL.
 */
const SIGNAL_PATH = "/v1/logs";

export const intakeBaseFromUrl = (url: string): string | undefined => {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return undefined;
  }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
    return undefined;
  }
  let path = parsed.pathname.replace(/\/+$/, "");
  if (path.endsWith(SIGNAL_PATH)) {
    path = path.slice(0, -SIGNAL_PATH.length);
  }
  return `${parsed.origin}${path}`;
};

/**
 * Resolve the endpoint from config. An explicit `publicKey` always wins, so a
 * non-keyed or proxied endpoint stays configurable.
 */
export const resolveIntakeEndpoint = (config: {
  intakeUrl?: string;
  intakeHost?: string;
  publicKey?: string;
}): ResolvedIntakeEndpoint | undefined => {
  const configured = config.intakeUrl ?? config.intakeHost;
  if (!configured) return undefined;

  const baseUrl = intakeBaseFromUrl(configured);
  if (!baseUrl) return undefined;

  const publicKey = config.publicKey ?? publicKeyFromIntakeUrl(configured);
  if (!publicKey) return undefined;

  return { baseUrl, publicKey };
};
