import { computeClickName } from "./element-name";
import type { WebEvent } from "./types";

export interface InteractionCaptureOptions {
  emit(event: WebEvent): void;
}

export interface InteractionCaptureHandle {
  /** Navigation counts as a click response for dead-click detection. */
  notifyNavigation(): void;
  teardown(): void;
}

const RAGE_WINDOW_MS = 1000;
const RAGE_RADIUS_PX = 30;
const RAGE_CLICK_COUNT = 4;
const DEAD_CLICK_TIMEOUT_MS = 800;
const MAX_SELECTOR_LENGTH = 200;

const INTERACTIVE_SELECTOR =
  "a,button,[role=button],input,select,textarea,label,summary,[tabindex],[onclick]";

/** Short, stable-ish selector for an element; never includes text content. */
export const computeSelector = (element: Element): string => {
  const testId = element.getAttribute("data-testid");
  if (testId) {
    return `[data-testid="${testId}"]`;
  }
  if (element.id) {
    return `#${element.id}`;
  }

  const segments: string[] = [];
  let current: Element | null = element;
  while (current && segments.length < 3) {
    let segment = current.tagName.toLowerCase();
    if (current.id) {
      segments.unshift(`#${current.id}`);
      break;
    }
    const classes = Array.from(current.classList).slice(0, 2);
    if (classes.length > 0) {
      segment += `.${classes.join(".")}`;
    }
    segments.unshift(segment);
    current = current.parentElement;
  }
  return segments.join(" > ").slice(0, MAX_SELECTOR_LENGTH);
};

interface RecentClick {
  time: number;
  x: number;
  y: number;
}

export const installInteractionCapture = (
  options: InteractionCaptureOptions,
): InteractionCaptureHandle => {
  // Monotonic counters, not timestamps. `performance.now()` is coarsened
  // (Chromium clamps it, and more so without cross-origin isolation), and the
  // click -> handler -> microtask -> MutationObserver path finishes well inside
  // one tick — measured 142/200 equal readings in the Chromium suite's own
  // environment. Any timestamp comparison therefore has to guess about
  // same-tick activity: `<=` called every snappy answered click dead, while `<`
  // let activity that merely *preceded* a click suppress a genuine dead one.
  // Counters captured at click time ask the exact question instead — "did
  // anything happen after this click?" — with no dependence on clock
  // resolution.
  let domActivityGeneration = 0;
  let navigationGeneration = 0;
  const recentClicks: RecentClick[] = [];
  // Not 0: performance.now() < 1s during early page life would read as
  // "just reported" and suppress a genuine first-second rage burst.
  let rageReportedAt = Number.NEGATIVE_INFINITY;
  const pendingDeadClickTimers = new Set<number>();

  const observer = new MutationObserver(() => {
    domActivityGeneration += 1;
  });
  try {
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      characterData: true,
    });
  } catch {
    // Without mutation signal, dead clicks are simply never reported.
  }

  const onClick = (event: MouseEvent): void => {
    try {
      const target = event.target;
      if (!(target instanceof Element)) {
        return;
      }

      const now = performance.now();
      const selector = computeSelector(target);
      const tag = target.tagName.toLowerCase();
      const name = computeClickName(target);

      options.emit({
        type: "click",
        body: name ? `click "${name}"` : `click ${selector}`,
        severity: "INFO",
        timeUnixMs: Date.now(),
        attributes: {
          "web.element.selector": selector,
          "web.element.tag": tag,
          "web.element.name": name,
        },
      });

      // Rage click: repeated clicks in a tight radius within the window.
      recentClicks.push({ time: now, x: event.clientX, y: event.clientY });
      while (
        recentClicks.length > 0 &&
        now - (recentClicks[0] as RecentClick).time > RAGE_WINDOW_MS
      ) {
        recentClicks.shift();
      }
      const clustered = recentClicks.filter(
        (click) =>
          Math.abs(click.x - event.clientX) <= RAGE_RADIUS_PX &&
          Math.abs(click.y - event.clientY) <= RAGE_RADIUS_PX,
      );
      if (
        clustered.length >= RAGE_CLICK_COUNT &&
        now - rageReportedAt > RAGE_WINDOW_MS
      ) {
        rageReportedAt = now;
        options.emit({
          type: "rage_click",
          body: name ? `rage click "${name}"` : `rage click ${selector}`,
          severity: "WARN",
          timeUnixMs: Date.now(),
          attributes: {
            "web.element.selector": selector,
            "web.element.tag": tag,
            "web.element.name": name,
            "web.click_count": clustered.length,
          },
        });
      }

      // Dead click: an interactive target where nothing observable follows.
      if (target.closest(INTERACTIVE_SELECTOR)) {
        const domGenAtClick = domActivityGeneration;
        const navGenAtClick = navigationGeneration;
        const timer = window.setTimeout(() => {
          pendingDeadClickTimers.delete(timer);
          try {
            // Unchanged counters mean nothing observable followed the click.
            if (
              domActivityGeneration === domGenAtClick &&
              navigationGeneration === navGenAtClick
            ) {
              options.emit({
                type: "dead_click",
                body: name ? `dead click "${name}"` : `dead click ${selector}`,
                severity: "WARN",
                timeUnixMs: Date.now(),
                attributes: {
                  "web.element.selector": selector,
                  "web.element.tag": tag,
                  "web.element.name": name,
                },
              });
            }
          } catch {
            // Never throw from a timer into the host.
          }
        }, DEAD_CLICK_TIMEOUT_MS);
        pendingDeadClickTimers.add(timer);
      }
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  document.addEventListener("click", onClick, { capture: true, passive: true });

  return {
    notifyNavigation() {
      navigationGeneration += 1;
    },
    teardown() {
      document.removeEventListener("click", onClick, { capture: true });
      observer.disconnect();
      for (const timer of pendingDeadClickTimers) {
        window.clearTimeout(timer);
      }
      pendingDeadClickTimers.clear();
    },
  };
};
